"""Regenerate the migration-0062 catalog state used by reconcile tests."""

from __future__ import annotations

import io
import os
import sqlite3
import subprocess
import sys
import tarfile
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
FIXED_TIME = "2026-10-27 00:00:00"
BASE_COMMIT = "115f18f"
_CHILD_MARKER = "NIGHTCRATE_LEGACY_FIXTURE_CHILD"


def _source(source_id: str, filename: str, parser: str, category: str):
    from nightcrate.catalog_loader.registry import CatalogSource

    return CatalogSource(
        source_id=source_id,
        category=category,
        display_name=f"Legacy fixture {source_id}",
        file_path=HERE / filename,
        version="legacy-fixture",
        source_url=None,
        license="test fixture",
        attribution="Generated fixture data",
        parser=parser,
    )


def _sql_literal(conn: sqlite3.Connection, value: object) -> str:
    return str(conn.execute("SELECT quote(?)", (value,)).fetchone()[0])


def _dump_table(conn: sqlite3.Connection, table: str) -> list[str]:
    columns = [row[1] for row in conn.execute(f'PRAGMA table_info("{table}")')]
    selected = ", ".join(f'"{column}"' for column in columns)
    rows = conn.execute(f'SELECT {selected} FROM "{table}" ORDER BY id').fetchall()
    names = ", ".join(f'"{column}"' for column in columns)
    return [
        f'INSERT INTO "{table}" ({names}) VALUES '
        f"({', '.join(_sql_literal(conn, value) for value in row)});"
        for row in rows
    ]


def _generate() -> None:
    from nightcrate.catalog_loader.barnard_loader import load_barnard
    from nightcrate.catalog_loader.loader import _load_source
    from nightcrate.catalog_loader.sharpless_loader import load_sharpless
    from nightcrate.db.migrations import apply_migrations

    with tempfile.TemporaryDirectory(prefix="nightcrate-legacy-") as temp_dir:
        db_path = Path(temp_dir) / "legacy.db"
        apply_migrations(db_path)
        conn = sqlite3.connect(db_path)
        conn.execute("PRAGMA foreign_keys = ON")

        main_source = _source("openngc", "NGC.csv", "openngc", "openngc")
        addendum = _source("openngc_addendum", "addendum.csv", "openngc", "openngc")
        sharpless = _source("vizier_sharpless", "sharpless.tsv", "sharpless", "vizier")
        barnard = _source("vizier_barnard", "barnard.tsv", "barnard", "vizier")

        results = [
            _load_source(conn, main_source, force=True),
            _load_source(conn, addendum, force=True),
            load_sharpless(
                conn,
                sharpless,
                crossref_path=HERE / "sharpless_crossref.csv",
                force=True,
            ),
            load_barnard(conn, barnard, force=True),
        ]
        failures = [result for result in results if result.status != "loaded"]
        if failures:
            raise RuntimeError(f"legacy loader failed: {failures}")

        conn.execute("UPDATE dso SET created_at = ?, updated_at = ?", (FIXED_TIME, FIXED_TIME))
        conn.execute("UPDATE dso_catalog_source SET loaded_at = ?", (FIXED_TIME,))
        for source_id, filename in (
            ("openngc", "NGC.csv"),
            ("openngc_addendum", "addendum.csv"),
            ("vizier_sharpless", "sharpless.tsv"),
            ("vizier_barnard", "barnard.tsv"),
        ):
            conn.execute(
                "UPDATE dso_catalog_source SET file_path = ? WHERE source_id = ?",
                (f"tests/fixtures/catalogs/legacy/{filename}", source_id),
            )
        conn.commit()

        lines = [
            "-- Generated by generate_legacy_fixture.py from the pre-reconcile loaders.",
            "PRAGMA foreign_keys = ON;",
            "BEGIN;",
            "DELETE FROM dso_designation;",
            "DELETE FROM dso;",
            "DELETE FROM dso_catalog_source;",
        ]
        for table in ("dso_catalog_source", "dso", "dso_designation"):
            lines.extend(_dump_table(conn, table))
        lines.extend(("COMMIT;", ""))
        (HERE / "legacy_dso.sql").write_text("\n".join(lines), encoding="utf-8")
        conn.close()


def main() -> None:
    if os.environ.get(_CHILD_MARKER) == "1":
        _generate()
        return

    repository = HERE.parents[4]
    archive = subprocess.run(
        ["git", "archive", BASE_COMMIT, "backend/src/nightcrate"],
        cwd=repository,
        check=True,
        capture_output=True,
    ).stdout
    with tempfile.TemporaryDirectory(prefix="nightcrate-legacy-source-") as temp_dir:
        source_root = Path(temp_dir)
        with tarfile.open(fileobj=io.BytesIO(archive), mode="r:") as bundle:
            bundle.extractall(source_root, filter="data")
        environment = os.environ.copy()
        environment[_CHILD_MARKER] = "1"
        old_pythonpath = environment.get("PYTHONPATH")
        extracted = str(source_root / "backend" / "src")
        environment["PYTHONPATH"] = (
            f"{extracted}{os.pathsep}{old_pythonpath}" if old_pythonpath else extracted
        )
        subprocess.run(
            [sys.executable, str(Path(__file__).resolve())],
            cwd=repository / "backend",
            env=environment,
            check=True,
        )


if __name__ == "__main__":
    main()
